using RestSharp;\nusing Serilog;\n\nnamespace AutomationFramework.API.BusinessLogic\n{\n    public class PetstoreAPIHelper\n    {\n        private readonly RestClient _client;\n\n        public PetstoreAPIHelper()\n        {\n            _client = new RestClient(\"https://petstore.swagger.io/v2/pet\");\n        }\n\n        public RestResponse CreatePet(object petPayload)\n        {\n            var request = new RestRequest(Method.POST);\n            request.AddJsonBody(petPayload);\n            var response = _client.Execute(request);\n            Log.Information(\"POST request sent with payload: {Payload}\", petPayload);\n            return response;\n        }\n\n        public RestResponse GetPetById(string petId)\n        {\n            var request = new RestRequest($\"/{petId}\", Method.GET);\n            var response = _client.Execute(request);\n            Log.Information(\"GET request sent for pet ID: {PetId}\", petId);\n            return response;\n        }\n\n        public RestResponse UpdatePet(string petId, object petPayload)\n        {\n            var request = new RestRequest($\"/{petId}\", Method.PUT);\n            request.AddJsonBody(petPayload);\n            var response = _client.Execute(request);\n            Log.Information(\"PUT request sent to update pet ID: {PetId} with payload: {Payload}\", petId, petPayload);\n            return response;\n        }\n\n        public RestResponse DeletePet(string petId)\n        {\n            var request = new RestRequest($\"/{petId}\", Method.DELETE);\n            var response = _client.Execute(request);\n            Log.Information(\"DELETE request sent for pet ID: {PetId}\", petId);\n            return response;\n        }\n    }\n}